                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append(cells)

    # The removable panel is the component with the most nearly uniform
    # rectangular footprint and a sparse set of 9 markers.
    def score(cells):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        area = (max(rs) - min(rs) + 1) * (max(cs) - min(cs) + 1)
        n9 = sum(g[r][c] == 9 for r, c in cells)
        return (len(cells) / area, -n9, area)

    target = max(comps, key=score)
    for r, c in target:
        g[r][c] = 0
    return g
